\begin{equation}\label{op:convex}
\begin{aligned}
& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
& & f(\mathbf{x}) \\
& \text{subject to}
& & g_i(\mathbf{x})\leq0,&\forall i=1,2,\dots m,\\
& & & h_j(\mathbf{x})=0,&\forall j=1,2,\dots,k,
\end{aligned}
\end{equation}

\label{thm:KKT}
	$(\mathbf{x},\mathbf{v},\boldsymbol{\mu})$ are a pair of primal and dual optimal solutions for~\eqref{op:convex} if and only if the following conditions hold.
	\begin{itemize}
		\item $\mathbf{x}$ is primal feasible, \textit{i.e.,} $g_i(\mathbf{x})\leq$ and $h_j(\mathbf{x})=0$ for all $i\in[m]$ and $j\in[k]$.
		\item $(\mathbf{v},\boldsymbol{\mu})$ is dual feasible, \textit{i.e.,} $\mathbf{v}_i\geq0$ for all $i\in[m]$.
		\item The Lagrange multiplier vanishes, \textit{i.e.,} $\nabla f(\mathbf{x}) + \sum_{i\in[m]}\mathbf{v}_i\nabla g_i(\mathbf{x}) + \sum_{j\in[k]}\boldsymbol{\mu}_j\nabla h_j(\mathbf{x})=0$.
		\item $(\mathbf{x},\mathbf{v},\boldsymbol{\mu})$ satisfy complementary slackness, \textit{i.e.,} $\mathbf{v}_i f_i(\mathbf{x})\geq0$ for all $i\in[m]$.
	\end{itemize}

