\label{def:ideal partition}
	Let $\mathcal{P}_{A,1}$ and $\mathcal{P}_{A,1-\tau}$ be defined as above. For each $\mathbf{v}^\text{ideal}\in\mathcal{P}_{A,1-\tau}$, define
	\begin{equation*}
	S_{\mathbf{v}^\text{ideal}} = \{\mathbf{v}^\text{ideal}+\mathcal{C}_{A,\Gamma(\mathbf{v}^{ideal})}\}\cap\mathcal{P}_{A,1}.
	\end{equation*}
	where $\Gamma(\mathbf{v}^\text{ideal})=\{i\in[\pm n]:\ \langle A_i,\mathbf{v}^\text{ideal}\rangle=1-\tau\}$ is the active walls of $\mathbf{v}^\text{ideal}$ and $\mathcal{C}_{A,\Gamma(\mathbf{v}^{ideal})}=\{\sum_{i\in\Gamma(\mathbf{v}^\text{ideal})}a_iA_i,\ \forall a_i\geq0\}$ is the cone spanned by the column of $A$ indexed by $\Gamma(\mathbf{v}^\text{ideal})$.

\begin{equation*}
	S_{\mathbf{v}^\text{ideal}} = \{\mathbf{v}^\text{ideal}+\mathcal{C}_{A,\Gamma(\mathbf{v}^{ideal})}\}\cap\mathcal{P}_{A,1}.
	\end{equation*}

\label{def:ideal solution}
	For any $t\geq0$, define the ideal solution $\mathbf{x}^\text{ideal}(t)$ at time $t$ as
	\begin{equation*}
	\mathbf{x}^\text{ideal}(t) = arg\,min_{\substack{\mathbf{x}\geq0,\\\mathbf{x}_i=0,\ \forall i\in\Gamma(\mathbf{v}^\text{ideal}(t))}}\|\mathbf{b}-A\mathbf{x}\|_2.
	\end{equation*}
	Also, let $\Gamma^*(\mathbf{v}^\text{ideal}(t))=\{i\in\Gamma(\mathbf{v}^\text{ideal}(t)):\ \mathbf{x}^\text{ideal}(t)\neq0\}$ to be the set of super active neurons.

\begin{equation*}
	\mathbf{x}^\text{ideal}(t) = arg\,min_{\substack{\mathbf{x}\geq0,\\\mathbf{x}_i=0,\ \forall i\in\Gamma(\mathbf{v}^\text{ideal}(t))}}\|\mathbf{b}-A\mathbf{x}\|_2.
	\end{equation*}

First, note that for each $\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}$, by the property of dual polytope, there exists an unique $\mathbf{z}\in{\mathbb R}_{\geq0}^{|\Gamma(\mathbf{v}^\text{ideal}(t))|}$ such that $\mathbf{v}=\mathbf{v}^\text{ideal}(t)+A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}$ where $\mathbf{z}$ can be thought of as the \textit{coordinates} of $\mathbf{v}$ in $S_{\mathbf{v}^\text{ideal}(t)}$. With this concept in mind, it is then sufficient to show that whenever neuron $i$ fires, $\mathbf{z}_i>\alpha$. The reason is that
\begin{align}
\mathbf{v}(t)-\alpha A\mathbf{s}(t) &= \mathbf{v}^\text{ideal}(t) + A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z} - \sum_{i\in\Gamma(\mathbf{v}(t))}\alpha A_i\nonumber\\
&= \mathbf{v}^\text{ideal}(t) + \sum_{i\in\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\Gamma(\mathbf{v}(t))}\mathbf{z}_iA_i + \sum_{i\in\Gamma(\mathbf{v}(t))}(\mathbf{z}_i-\alpha)A_i.\label{eq:ideal SNN fire}
\end{align}
As a result, if $\mathbf{z}_i-\alpha>0$ for every $i\in\Gamma(\mathbf{v}(t))$, then we have $\mathbf{v}(t)-\alpha A\mathbf{s}(t)\in S_{\mathbf{v}^\text{ideal}(t)}$ because every new coordinates are still non-negative. See Figure~\ref{fig:coordinate} for an example.

