\vspace{3mm}

\begin{claim}\label{claim:ideal SNN stay after fire coordinate}
	There exists a polynomial $\alpha(\cdot)$ such that when $0<\alpha\leq{\mathrm{poly}}(\frac{\tau\cdot\gamma(A)}{n\cdot\lambda_{\max}})$ and $\mathbf{v}(t)=\mathbf{v}^\text{ideal}(t)+A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}\in S_{\mathbf{v}^\text{ideal}(t)}$ for some $t\geq0$, if $i\in\Gamma(\mathbf{v}(t))$, then $\mathbf{z}_i>\alpha$.
\end{claim}
\begin{proof}[Proof of Claim~\ref{claim:ideal SNN stay after fire coordinate}]
	The proof consists of two steps. First, we are going to show that for any $t\geq0$, $\mathbf{v}(t)$ is close to $\mathbf{v}^\text{ideal}(t)$. Concretely, if $\alpha\leq\frac{\tau}{m}$, then $\|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2\leq\tau\lambda_{\max}$. Second, we are going to show that once we pick $\alpha$ small enough, then for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, the wall $W_i$ is far away from the $\alpha$-level set in $S_{\mathbf{v}^\text{ideal}(t)}$. Thus, whenever neuron $i$ fires, $\mathbf{z}_i>\alpha$.

	The first step is a key observation that the distance between $\mathbf{v}(t)$ and $\mathbf{v}^\text{ideal}(t)$ would not increase after the neurons fire spikes. The main reason is that neuron $i$ fires at time $t$ if and only if $A_i^\top\mathbf{v}(t)>1$. As a result,
	\begin{align*}
	\|\left(\mathbf{v}(t)-\alpha A\mathbf{s}(t)\right)-\mathbf{v}^\text{ideal}(t)\|_2^2 &= \|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2^2 + \alpha^2\|A\mathbf{s}(t)\|_2^2 - 2\alpha\left(A\mathbf{s}(t)\right)^\top\left(\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\right)\\
	& = \|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2^2 + \alpha^2\|A\mathbf{s}(t)\|_2^2 -2\alpha\sum_{i\in\Gamma(\mathbf{v}(t))}A_i^\top\left(\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\right)\\
	&\leq\|\mathbf{v}(t)-\mathbf{v}^\text{ideal}(t)\|_2^2 + \alpha^2|\Gamma(\mathbf{v}(t))|^2 -2\alpha\tau|\Gamma(\mathbf{v}(t))|.
	\end{align*}
	That is, if $\alpha\leq\frac{\tau}{m}$, then $\|\left(\mathbf{v}(t)-\alpha A\mathbf{s}(t)\right)-\mathbf{v}^\text{ideal}(t)\|_2$ would not increase after some neurons fire. Furthermore, the longest distance between $\mathbf{v}(t)$ and $\mathbf{v}^\text{ideal}(t)$ would then be $\tau\lambda_{\max}$.

	The second step is rather complicated. Let us start with some definitions. Recall that for any $i\in[\pm n]$, the wall $i$ is defined as $W_i=\{\mathbf{v}\in{\mathbb R}^m:\ A_i^\top\mathbf{v}=1 \}$. Now, define the $\alpha$-level set of $i$ in $S_{\mathbf{v}^\text{ideal}(t)}$ as
	$$
	L_{\mathbf{v}^\text{ideal}(t),i,\alpha} = \{\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}:\ \mathbf{v}=\mathbf{v}^\text{ideal}(t)+A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z},\ \mathbf{z}_i=\alpha\}. 
	$$
	That is, $L_{\mathbf{v}^\text{ideal}(t),i,\alpha} $ consists of the set of points in $S_{\mathbf{v}^\text{ideal}(t)}$ that has the $i^\text{th}$ coordinate to be $\alpha$.

	\begin{claim}[furtherest point in $S_{\mathbf{v}^\text{ideal}}$]\label{claim:furthest point in safe region}
		For any $t\geq0$, let $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}$ be the unique point $\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}$ such that for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, $A_i^\top\left(\mathbf{v}-\mathbf{v}^\text{ideal}(t)\right)=\tau$. Then, we have $\|\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)\|_2=\max_{\mathbf{v}\in S_{\mathbf{v}^\text{ideal}(t)}}\|\mathbf{v}-\mathbf{v}^\text{ideal}(t)\|_2$.
	\end{claim}
	\begin{proof}[Proof of Claim~\ref{claim:furthest point in safe region}]
		Let us prove by contradiction. Suppose $\mathbf{v}^*\in S_{\mathbf{v}^\text{ideal}(t)}$ such that $\|\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)\|_2<\|\mathbf{v}^*-\mathbf{v}^\text{ideal}(t)\|_2$. To simplify the notations, let $\mathbf{v}_{\Gamma}=\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)$ and $\mathbf{v}=\mathbf{v}^*-\mathbf{v}^\text{ideal}(t)$.

		By definition, we have $A_i^\top\mathbf{v}_\Gamma=\tau$ for all $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$ and $\mathbf{v}=A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}_\Gamma$ for some $\mathbf{z}_\Gamma\in{\mathbb R}_{>0}$. On the other hand, we also have $0\leq A_i^\top\mathbf{v}\leq\tau$ for all $i\in\Gamma(\mathbf{v}^\text{ideal}(t)$.

		Now, look at the quantity $\mathbf{v}_{\Gamma}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)$. Note that since $\|\mathbf{v}\|_2>\|\mathbf{v}_\Gamma\|_2$, we have $\mathbf{v}_{\Gamma}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)>0$. Also, for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, we have $A_i^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)\leq0$. Using the fact that $\mathbf{v}=A_{\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}_\Gamma$ for some $\mathbf{z}_\Gamma\in{\mathbb R}_{>0}$, we have
		\begin{align*}
		0 < \mathbf{v}_{\Gamma}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)&=\mathbf{z}_\Gamma^\top A_{\Gamma(\mathbf{v}^\text{ideal}(t))}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)\\
		&= \mathbf{z}_\Gamma^\top\mathbf{u}\leq0,
		\end{align*}
		where $\mathbf{u}=A_{\Gamma(\mathbf{v}^\text{ideal}(t))}^\top\left(\mathbf{v}-\mathbf{v}_\Gamma\right)\in{\mathbb R}_{\leq0}^{|\Gamma(\mathbf{v}^\text{ideal}(t))|}$. That is, we reach a contradiction and thus $\|\mathbf{v}\|_2\leq\|\mathbf{v}_\Gamma\|_2$ and we conclude that $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}$ is the furtherest point from $\mathbf{v}^\text{ideal}(t)$ in $S_{\mathbf{v}^\text{ideal}(t)}$.
	\end{proof}
	\begin{claim}[intersection of wall and $\alpha$-level set is far]\label{claim:ideal SNN intersection is far}
		When $0<\alpha\leq\tau^2\cdot\gamma(A)^3$, for any $t\geq0$ and $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, we have
		$$
		\min_{\mathbf{v}:\ \mathbf{v}\in W_i\cap L_{\mathbf{v}^\text{ideal}(t),i,\alpha}}\|\mathbf{v}-\mathbf{v}^\text{ideal}(t)\|_2>\|\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}-\mathbf{v}^\text{ideal}(t)\|_2.
		$$
	\end{claim}
	\begin{proof}[Proof of Claim~\ref{claim:ideal SNN intersection is far}]
		First, let us write $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}=\mathbf{v}^\text{ideal}(t)+\sum_{i\in\Gamma(\mathbf{v}^\text{ideal}(t))}\mathbf{z}_iA_i$ where $\mathbf{z}_i\geq\tau\cdot\gamma(A)$ by Definition~\ref{def:nice}. Furthermore, for any $i\in\Gamma(\mathbf{v}^\text{ideal}(t))$, we have
		\begin{equation*}
		\text{dist}\left(\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))},\text{span}(A_{\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\{i\}})\right)\geq|\mathbf{z}_i|\cdot\text{dist}\left(A_i,\text{span}(A_{\Gamma(\mathbf{v}^\text{ideal}(t))\backslash\{i\}})\right)\geq\tau\cdot\gamma(A)^2,
		\end{equation*}
		where the last inequality follows Definition~\ref{def:nice}. Namely, if we pick $0<\alpha<\tau^2\cdot\gamma(A)^3$, then
		\begin{equation*}
		\text{dist}\left(\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))},L_{\mathbf{v}^\text{ideal}(t),i,\alpha}\right)>0
		\end{equation*}
		and $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}\in\text{Cone}(A_i,L_{\mathbf{v}^\text{ideal}(t),i,\alpha})$ because $\mathbf{z}_i\geq\gamma(A)$. Finally, observe that for any $\mathbf{v}\in W_i\cap L_{\mathbf{v}^\text{ideal}(t),i,\alpha}$, we have $\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}^\top\left(\mathbf{v}-\mathbf{v}_{\Gamma(\mathbf{v}^\text{ideal}(t))}\right)>0$. This completes the proof of Claim~\ref{claim:ideal SNN intersection is far}.
	\end{proof}
	Combine Claim~\ref{claim:furthest point in safe region} and Claim~\ref{claim:ideal SNN intersection is far}, we know that when neuron $i$ fires, the corresponding coordinate $\mathbf{z}_i$ will be at least $\alpha$. This completes the proof of Claim~\ref{claim:ideal SNN stay after fire coordinate}.
\end{proof}
