	\end{enumerate}

The lemma is directly followed by the following property of conic projection. For any $A\in{\mathbb R}^{m\times n}$, $\mathbf{b}\in{\mathbb R}^m$, and $\Gamma\subseteq[\pm n]$ be a valid set, we have $\mathbf{b}^\top A\mathbf{x}_{A,\mathbf{b},\Gamma}=\|A\mathbf{x}_{A,\mathbf{b},\Gamma}\|_2^2$. In the following, we are going to first prove this property of conic projection and then use it to prove the lemma.

Let us rewrite the definition of conic projection as an optimization program.
\begin{equation}\label{op:conicproj}
\begin{aligned}
& \underset{\mathbf{x}\in{\mathbb R}^n}{\text{minimize}}
& & \frac{1}{2}\|\mathbf{b}-A\mathbf{x}\|_2^2 \\
& \text{subject to}
& & \mathbf{x}_j\geq0,\ j\in\Gamma,\\
& & & \mathbf{x}_i=0,\ i,-i\notin\Gamma.
\end{aligned}
\end{equation}
Let $\mathbf{y}$ be the dual variable of~\eqref{op:conicproj} and $\mathbf{y}^*$ be the optimal dual value, the Lagrangian of~\eqref{op:conicproj} is
\begin{equation*}
\mathcal{L}(\mathbf{x}) = \frac{1}{2}\|\mathbf{b}-A\mathbf{x}\|_2^2-\mathbf{y}^\top\mathbf{x},
\end{equation*}
and its gradient is
\begin{equation*}
\nabla_{\mathbf{x}}\mathcal{L}(\mathbf{x}) = A^\top A\mathbf{x} - A^\top\mathbf{b} - \mathbf{y}.
\end{equation*}
By the KKT condition, we know that the optimal primal solution $\mathbf{x}_{A,\mathbf{b},\Gamma}$ and the optimal dual solution $\mathbf{y}^*$ make the gradient of the Lagrangian diminish.
\begin{equation}\label{eq:idealalgorithm-conicproj-KKT-gradient}
\nabla_{\mathbf{x}}\mathcal{L}(\mathbf{x}_{A,\mathbf{b},\Gamma}) = A^\top A\mathbf{x}_{A,\mathbf{b},\Gamma} - A^\top\mathbf{b} - \mathbf{y}^*=0,
\end{equation}
and the complementary slackness
\begin{equation}\label{eq:idealalgorithm-conicproj-KKT-cs}
\mathbf{x}_{A,\mathbf{b},\Gamma}^\top\mathbf{y}^*=0.
\end{equation}
By~\eqref{eq:idealalgorithm-conicproj-KKT-gradient} and~\eqref{eq:idealalgorithm-conicproj-KKT-cs}, we have
\begin{equation*}\label{eq:idealalgorithm-conicproj-orthogonal}
(A\mathbf{x}_{A,\mathbf{b},\Gamma})^\top(\mathbf{b}-A\mathbf{x}_{A,\mathbf{b},\Gamma})=0.
\end{equation*}
As a result, $\mathbf{b}^\top A\mathbf{x}_{A,\mathbf{b},\Gamma}=\|A\mathbf{x}_{A,\mathbf{b},\Gamma}\|_2^2$.

This completes the proof of Lemma~\ref{lem:ideal solution properties}.

